// ========================================================
// UMKMENSE PRO - UNIVERSAL WHATSAPP INGESTION & NORMALIZER
// (Mendukung: Meta Cloud API, Fonnte, Evolution API, Wablas, Baileys, Whacenter)
// ========================================================
const item = $json.body || $json;

// 0. Filter Out Pesan Keluar (fromMe), Group Chat (@g.us), dan Broadcast (@broadcast)
if (item.data && item.data.key) {
  if (item.data.key.fromMe) {
    return []; // Abaikan pesan yang dikirim oleh bot / nomor ini sendiri
  }
  const rJid = String(item.data.key.remoteJid || '');
  if (rJid.includes('@g.us') || rJid.includes('status@broadcast') || rJid.includes('@broadcast')) {
    return []; // Abaikan pesan grup dan status WhatsApp
  }
}

let senderPhone = '';
let senderName = 'Bos UMKM';
let textPrompt = '';
let messageType = 'text';
let mediaUrl = null;
let hasMedia = false;
let mediaRejected = false;
let sourceMessageId = '';

// 1. Format Payload Evolution API / Baileys
if (item.data && (item.data.key || item.data.message)) {
  const key = item.data.key || {};
  sourceMessageId = String(key.id || item.data.messageId || item.messageId || '');
  let msg = item.data.message || {};

  // Unpack ephemeral / viewOnce jika ada
  if (msg.ephemeralMessage && msg.ephemeralMessage.message) {
    msg = msg.ephemeralMessage.message;
  }
  if (msg.viewOnceMessage && msg.viewOnceMessage.message) {
    msg = msg.viewOnceMessage.message;
  }
  if (msg.viewOnceMessageV2 && msg.viewOnceMessageV2.message) {
    msg = msg.viewOnceMessageV2.message;
  }

  const remoteJid = String(key.remoteJid || '');
  if (remoteJid.includes('@g.us') || remoteJid.includes('@broadcast')) {
    return [];
  }

  senderPhone = remoteJid.replace(/[^0-9]/g, '');
  let rawName = (item.data.pushName || item.pushName || item.senderName || '').trim();
  senderName = (rawName && rawName !== 'Você' && rawName !== 'You') ? rawName : 'Bos UMKM';

  if (msg.conversation) {
    textPrompt = msg.conversation.trim();
  } else if (msg.extendedTextMessage) {
    textPrompt = (msg.extendedTextMessage.text || '').trim();
  } else if (msg.videoMessage) {
    mediaRejected = true;
    messageType = 'text';
    textPrompt = 'Video tidak didukung. Mohon kirim foto struk sebagai gambar (JPG/PNG/WebP), bukan video.';
  } else if (msg.imageMessage) {
    messageType = 'photo_receipt';
    hasMedia = true;
    textPrompt = (msg.imageMessage.caption || '').trim() || 'Foto Struk Masuk';
  } else if (msg.audioMessage) {
    messageType = 'voice_note';
    hasMedia = true;
    textPrompt = 'Audio Voice Note Masuk';
  } else {
    // Abaikan reactionMessage, stickerMessage, protocolMessage, pollUpdateMessage, dll.
    return [];
  }
}
// 2. Format Payload Fonnte / Wablas
else if (item.sender || item.phone) {
  sourceMessageId = String(item.messageId || item.message_id || item.id || '');
  senderPhone = String(item.sender || item.phone).replace(/[^0-9]/g, '');
  senderName = item.name || item.pushName || 'Bos UMKM';
  textPrompt = (item.message || item.text || '').trim();
  if (item.url || item.file) {
    mediaUrl = item.url || item.file;
    hasMedia = true;
    if (item.type === 'audio' || item.type === 'voice') messageType = 'voice_note';
    else if (item.type === 'video') { messageType = 'text'; mediaRejected = true; textPrompt = 'Video tidak didukung. Mohon kirim foto struk sebagai gambar (JPG/PNG/WebP), bukan video.'; }
    else messageType = 'photo_receipt';
  }
}
// 3. Format Payload Meta WhatsApp Business Cloud API
else if (item.entry && item.entry[0] && item.entry[0].changes) {
  const changes = item.entry[0].changes[0].value;
  const contact = changes.contacts ? changes.contacts[0] : {};
  const message = changes.messages ? changes.messages[0] : {};

  sourceMessageId = String(message.id || '');
  senderPhone = String(message.from || '').replace(/[^0-9]/g, '');
  senderName = contact.profile ? contact.profile.name : 'Bos UMKM';

  if (message.type === 'text') {
    textPrompt = message.text.body.trim();
  } else if (message.type === 'audio' || message.type === 'voice') {
    messageType = 'voice_note';
    hasMedia = true;
    textPrompt = 'Audio Voice Note Masuk';
  } else if (message.type === 'video') {
    mediaRejected = true;
    messageType = 'text';
    textPrompt = 'Video tidak didukung. Mohon kirim foto struk sebagai gambar (JPG/PNG/WebP), bukan video.';
  } else if (message.type === 'image') {
    messageType = 'photo_receipt';
    hasMedia = true;
    textPrompt = (message.image.caption || '').trim() || 'Foto Struk Masuk';
  } else if (message.type === 'interactive') {
    textPrompt = message.interactive.button_reply?.id || message.interactive.list_reply?.id || '';
  } else {
    return [];
  }
}
// 4. Fallback Generic Payload
else {
  sourceMessageId = String(item.messageId || item.message_id || '');
  senderPhone = String(item.from || item.chatId || item.id || '').replace(/[^0-9]/g, '');
  senderName = item.pushName || item.senderName || 'Bos UMKM';
  textPrompt = String(item.message || item.text || item.caption || '').trim();
}

// Abaikan jika tidak ada teks dan tidak ada media
if (!textPrompt && !hasMedia) {
  return [];
}

// Abaikan jika nomor pengirim tidak valid
if (!senderPhone || senderPhone.length < 5) {
  return [];
}

// Normalisasi Shortcut Command WhatsApp
const lowerPrompt = textPrompt.toLowerCase().trim();
const normalizedAmountText = (value) => value.replace(/(\d+(?:[.,]\d+)?)\s*(k|rb|ribu|jt|juta)\b/gi, (_, n, unit) => { const v = Number(String(n).replace(',', '.')); const factor = /^(k|rb|ribu)$/i.test(unit) ? 1000 : 1000000; return String(Math.round(v * factor)); });
textPrompt = normalizedAmountText(textPrompt);
const requestedReport = /^(\/)?rekap\b/.test(lowerPrompt) ? 'rekap' : (/^(\/)?saldo\b|^cek saldo\b/.test(lowerPrompt) ? 'saldo' : (/^(\/)?riwayat\b|^histori\b|^riwayat transaksi\b/.test(lowerPrompt) ? 'riwayat' : (/^(\/)?kasbon\b|^daftar kasbon\b/.test(lowerPrompt) ? 'kasbon' : (/^(\/)?reminder\b|^tagih kasbon\b/.test(lowerPrompt) ? 'reminder' : null))));
const requestedDate = (lowerPrompt.match(/tanggal\s+\d{1,2}(?:[\/-]\d{1,2}(?:[\/-]\d{2,4})?|\s+[a-z]+(?:\s+\d{4})?)/i) || [null])[0];
const reportPeriod = /keseluruhan|semua|all/.test(lowerPrompt) ? 'keseluruhan' : (/minggu ini|pekan ini/.test(lowerPrompt) ? 'minggu ini' : (/bulan ini/.test(lowerPrompt) ? 'bulan ini' : (/kemarin|hari kemarin/.test(lowerPrompt) ? 'kemarin' : (/\b\d+\s+hari\s+lalu\b/.test(lowerPrompt) ? lowerPrompt.match(/\b\d+\s+hari\s+lalu\b/)[0] : (/hari ini|sekarang|today/.test(lowerPrompt) ? 'hari ini' : 'keseluruhan')))));

if (lowerPrompt === '/start' || lowerPrompt === 'menu' || lowerPrompt === 'panduan' || lowerPrompt === 'bantuan' || lowerPrompt === 'help' || lowerPrompt === '/menu') {
  textPrompt = 'Tampilkan panduan lengkap semua fitur UMKMense Pro terbaru versi WhatsApp.';
} else if (['halo', 'hai', 'hi', 'hey', 'p', 'm', 'ass', 'as', 'assalamualaikum', 'aslm', 'salam', 'permisi', 'tes', 'test', 'ping', 'halo bot', 'halo min', 'halo mas', 'selamat pagi', 'selamat siang', 'selamat sore', 'selamat malam'].includes(lowerPrompt)) {
  textPrompt = `Halo! Nama saya ${senderName}. Tolong sapa saya dengan ramah menyebut nama saya (${senderName}) dan berikan petunjuk singkat penggunaan bot serta instruksikan saya untuk mengetik menu untuk melihat fitur lengkap.`;
} else if (lowerPrompt === '/rekap' || lowerPrompt === 'rekap' || lowerPrompt === 'rekap hari ini') {
  textPrompt = 'Berapa rekap pemasukan, pengeluaran, dan keuntungan usaha saya hari ini?';
} else if (lowerPrompt === '/saldo' || lowerPrompt === 'saldo' || lowerPrompt === 'cek saldo') {
  textPrompt = 'Berapa saldo kas dan performa keuangan usaha saya saat ini?';
} else if (lowerPrompt === '/kasbon' || lowerPrompt === 'kasbon' || lowerPrompt === 'daftar kasbon') {
  textPrompt = 'Tampilkan daftar catatan kasbon pelanggan dan hutang ke supplier yang belum lunas beserta totalnya.';
} else if (lowerPrompt === '/reminder' || lowerPrompt === 'reminder' || lowerPrompt === 'tagih kasbon') {
  textPrompt = 'Periksa tagihan kasbon pelanggan yang mendekati atau melewati jatuh tempo dan buatkan draf pesan pengingat WhatsApp yang sangat sopan dan ramah untuk menagih dengan total sisa kasbon yang benar.';
}


// Deteksi Perintah Ekspor Spreadsheet Excel
let isMenu = false;
if (['/start', 'menu', 'panduan', 'bantuan', 'help', '/menu'].includes(lowerPrompt)) {
  isMenu = true;
}

let isGreeting = false;
const greetingKeywords = ['halo', 'hai', 'hi', 'hey', 'p', 'm', 'ass', 'as', 'assalamualaikum', 'aslm', 'salam', 'permisi', 'tes', 'test', 'ping', 'halo bot', 'halo min', 'halo mas', 'selamat pagi', 'selamat siang', 'selamat sore', 'selamat malam'];
if (greetingKeywords.includes(lowerPrompt)) {
  isGreeting = true;
}

const isFastResponse = isMenu || isGreeting;

let isExport = false;
if (
  lowerPrompt === 'export' ||
  lowerPrompt === '/export' ||
  lowerPrompt === 'export excel' ||
  lowerPrompt === 'export spreadsheet' ||
  lowerPrompt === 'download excel' ||
  lowerPrompt === 'download laporan' ||
  lowerPrompt === 'unduh laporan' ||
  lowerPrompt === 'laporan excel' ||
  lowerPrompt === 'rekap excel' ||
  lowerPrompt === 'file excel' ||
  lowerPrompt === 'kirim excel' ||
  lowerPrompt === 'buat excel' ||
  lowerPrompt === 'unduh excel' ||
  lowerPrompt === 'excel' ||
  lowerPrompt.startsWith('export') ||
  lowerPrompt.startsWith('download') ||
  lowerPrompt.includes('file excel') ||
  lowerPrompt.includes('laporan excel')
) {
  isExport = true;
}

const understoodInput = isMenu || isGreeting || isExport || hasMedia || /\b(jual|menjual|beli|membeli|bayar|pemasukan|pengeluaran|kasbon|lunas|pelunasan|saldo|rekap|riwayat|laporan|reminder|tagih|koreksi|ralat|batalkan|void|export|excel|download)\b/i.test(lowerPrompt);
if (!understoodInput) { isGreeting = true; textPrompt = `Halo! Nama saya ${senderName}. Tolong sapa saya dengan ramah menyebut nama saya (${senderName}) dan arahkan saya mengetik menu untuk melihat semua fitur.`; }

return {
  is_export: isExport,
  is_menu: isMenu,
  is_greeting: isGreeting,
  is_fast_response: isFastResponse,
  chat_id: senderPhone,
  user_id: senderPhone,
  source_message_id: sourceMessageId,
  user_name: senderName,
  user_prompt: textPrompt,
  requested_report: requestedReport,
  report_period: reportPeriod,
  report_date: requestedDate,
  message_type: messageType,
  has_media: hasMedia,
  media_rejected: mediaRejected,
  media_url: mediaUrl,
  platform: 'whatsapp',
  received_at: new Date().toISOString()
};
// UMKMENSE_VIDEO_REJECT_V1: video hanya ditolak, foto tetap diterima.

// ========================================================
// ATTACH WHATSAPP MULTIMODAL DATA (ALL-PROVIDER TRI-MATRIX)
// VOICE-TO-TEXT: Groq Whisper (P1) -> Gemini 3.5 Transcribe (P2) -> Gemini Flash Lite (P3) -> Vibe Groq 4.5 / Luna (P4)
// VISION-TO-TEXT: Gemini 3.5 Flash Lite -> Groq Qwen 3.6 -> Vibe Luna
// ========================================================
const prev = $('WhatsApp Input Normalizer').first().json;

if (!prev.has_media) {
  return $input.all();
}

const rawPayload = $('WhatsApp Universal Ingestion Webhook').first().json;
const item = rawPayload.body || rawPayload;

const GROQ_API_KEY = $env.GROQ_API_KEY || '';
const VIBE_API_KEY = $env.VIBE_API_KEY || '';
const GEMINI_KEYS = [$env.GEMINI_API_KEY_1, $env.GEMINI_API_KEY_2, $env.GEMINI_API_KEY_3].filter(Boolean);

if (!GROQ_API_KEY && !VIBE_API_KEY && GEMINI_KEYS.length === 0) {
  throw new Error('Tidak ada kredensial multimodal yang dikonfigurasi.');
}

let base64Data = item.data?.message?.base64 || item.data?.base64 || item.base64 || '';
if (typeof base64Data === 'string' && base64Data.includes('base64,')) {
  base64Data = base64Data.split('base64,')[1];
}

let promptText = prev.user_prompt;
// UMKMENSE_MEDIA_LIMITS_V1
const MAX_MEDIA_BYTES = 12 * 1024 * 1024;
const MAX_AUDIO_BYTES = 8 * 1024 * 1024;
const MAX_IMAGE_BYTES = 10 * 1024 * 1024;
const mediaBytes = (value) => { if (typeof value !== 'string') return 0; const clean = value.replace(/^data:[^;]+;base64,/, ''); return Math.floor(clean.length * 3 / 4); };
if (prev.has_media) {
  const bytes = mediaBytes(base64Data);
  const limit = prev.message_type === 'voice_note' ? MAX_AUDIO_BYTES : MAX_IMAGE_BYTES;
  if (!bytes || bytes > MAX_MEDIA_BYTES || bytes > limit) {
    const label = prev.message_type === 'voice_note' ? 'Voice Note' : 'foto struk';
    return [{ json: { ...prev, has_media: false, message_type: 'text', media_rejected: true, user_prompt: 'Media terlalu besar untuk diproses. Minta pengguna mengirim ' + label + ' yang lebih kecil (maksimal ' + Math.round(limit / 1024 / 1024) + ' MB).' } }];
  }
}

const binary = {};

// ========================================================
// 1. CABANG VOICE NOTE (VOICE TO TEXT)
// ========================================================
if (prev.message_type === 'voice_note') {
  if (base64Data && typeof base64Data === 'string' && base64Data.length > 0) {
    let audioMime = item.data?.message?.audioMessage?.mimetype || item.data?.message?.message?.audioMessage?.mimetype || 'audio/ogg';
    if (audioMime.includes(';')) {
      audioMime = audioMime.split(';')[0].trim();
    }

    let rawTranscript = '';

    // [PRIORITAS 1: GROQ WHISPER LARGE V3 TURBO - TERBAIK DI BIDANG AUDIO]
    try {
      const boundary = '----WAGroq' + Date.now();
      const audioBuffer = Buffer.from(base64Data, 'base64');
      const ext = audioMime.includes('ogg') ? 'ogg' : (audioMime.includes('mp4') ? 'm4a' : 'wav');
      const body = Buffer.concat([
        Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="model"\r\n\r\nwhisper-large-v3-turbo\r\n'),
        Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="language"\r\n\r\nid\r\n'),
        Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="file"; filename="audio.' + ext + '"\r\nContent-Type: ' + audioMime + '\r\n\r\n'),
        audioBuffer,
        Buffer.from('\r\n--' + boundary + '--\r\n')
      ]);

      const groqRes = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.groq.com/openai/v1/audio/transcriptions',
        headers: {
          'Authorization': 'Bearer ' + GROQ_API_KEY,
          'Content-Type': 'multipart/form-data; boundary=' + boundary,
          'Content-Length': body.length
        },
        body: body,
        json: true, timeout: 15000
      });

      if (groqRes && groqRes.text && groqRes.text.trim()) {
        rawTranscript = groqRes.text.trim();
      }
    } catch (err) {}

    // [PRIORITAS 2: GEMINI 3.5 TRANSCRIBE - 3 AKUN GEMINI FAILOVER]
    if (!rawTranscript) {
      for (let i = 0; i < GEMINI_KEYS.length; i++) {
        const activeKey = GEMINI_KEYS[i];
        try {
          const res = await this.helpers.httpRequest({
            method: 'POST',
            url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-transcribe:generateContent?key=' + activeKey,
            headers: { 'Content-Type': 'application/json' },
            body: {
              contents: [{
                role: 'user',
                parts: [
                  { inlineData: { mimeType: audioMime, data: base64Data } },
                  { text: 'Transkrip audio percakapan pembukuan UMKM ini ke Bahasa Indonesia secara persis dan akurat.' }
                ]
              }]
            },
            json: true, timeout: 15000
          });

          if (res && res.candidates && res.candidates.length > 0) {
            const parts = res.candidates[0].content?.parts || [];
            for (const p of parts) {
              if (p.audioTranscription && p.audioTranscription.text) {
                rawTranscript += p.audioTranscription.text + ' ';
              } else if (p.text) {
                rawTranscript += p.text + ' ';
              }
            }
            rawTranscript = rawTranscript.trim();
            if (rawTranscript) break;
          }
        } catch (err) {}
      }
    }

    // [PRIORITAS 3: GEMINI 3.5 FLASH LITE MULTIMODAL AUDIO]
    if (!rawTranscript) {
      for (let i = 0; i < GEMINI_KEYS.length; i++) {
        const activeKey = GEMINI_KEYS[i];
        try {
          const res = await this.helpers.httpRequest({
            method: 'POST',
            url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent?key=' + activeKey,
            headers: { 'Content-Type': 'application/json' },
            body: {
              contents: [{
                role: 'user',
                parts: [
                  { inlineData: { mimeType: audioMime, data: base64Data } },
                  { text: 'Dengarkan rekaman suara ini dan tuliskan kata-kata transkripsinya secara persis dalam Bahasa Indonesia.' }
                ]
              }]
            },
            json: true, timeout: 15000
          });

          if (res && res.candidates && res.candidates.length > 0) {
            const textPart = res.candidates[0].content?.parts?.[0]?.text || '';
            if (textPart.trim()) {
              rawTranscript = textPart.trim();
              break;
            }
          }
        } catch (err) {}
      }
    }

    // [PRIORITAS 4: VIBE AI VOICE-TO-TEXT - 3-TIER MODEL MATRIX]
    // Tier 1: free/gpt-5.6-luna -> Tier 2: free/grok-4.5 -> Tier 3: free/grok-4.6
    if (!rawTranscript) {
      const vibeVoiceCandidates = ['free/gpt-5.6-luna', 'free/grok-4.5', 'free/grok-4.6'];
      for (const vModel of vibeVoiceCandidates) {
        try {
          const vibeRes = await this.helpers.httpRequest({
            method: 'POST',
            url: 'https://vibe.madewgn.dev/v1/chat/completions',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ' + VIBE_API_KEY
            },
            body: {
              model: vModel,
              messages: [{
                role: 'user',
                content: [
                  { type: 'text', text: 'Transkripsikan pesan suara rekaman pembukuan ini ke Bahasa Indonesia secara persis:' },
                  { type: 'input_audio', input_audio: { data: base64Data, format: audioMime.includes('ogg') ? 'ogg' : 'wav' } }
                ]
              }]
            },
            json: true,
            timeout: 5000
          });

          const content = vibeRes?.choices?.[0]?.message?.content || '';
          if (content && !content.toLowerCase().includes('no audio support') && !content.toLowerCase().includes('tidak mendukung') && !content.toLowerCase().includes('transkripsi gagal') && !content.toLowerCase().includes('audio tidak tersedia')) {
            rawTranscript = content.trim();
            break;
          }
        } catch (err) {}
      }
    }

    if (rawTranscript && !rawTranscript.includes('[HENING]')) {
      promptText = rawTranscript;
    } else {
      promptText = 'Pengguna mengirimkan Voice Note yang suaranya tidak terdengar atau hening. Beritahukan dengan ramah bahwa suaranya belum terdengar jelas dan minta kirim ulang rekaman suaranya.';
    }
  } else {
    promptText = 'Pengguna mengirimkan Voice Note tanpa file data suara yang valid. Minta kirim ulang rekaman suaranya.';
  }
}

// ========================================================
// 2. CABANG FOTO STRUK (VISION TO TEXT)
// ========================================================
else if (prev.message_type === 'photo_receipt') {
  let extractedReceiptText = '';

  if (base64Data && typeof base64Data === 'string' && base64Data.length > 0) {
    let imgMime = item.data?.message?.imageMessage?.mimetype || 'image/jpeg';
    if (imgMime.includes(';')) imgMime = imgMime.split(';')[0].trim();

    // [PRIORITAS 1: GOOGLE GEMINI 3.5 FLASH LITE VISION - TERBAIK DI BIDANG VISION (3 AKUN)]
    for (let i = 0; i < GEMINI_KEYS.length; i++) {
      const activeKey = GEMINI_KEYS[i];
      try {
        const res = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent?key=' + activeKey,
          headers: { 'Content-Type': 'application/json' },
          body: {
            contents: [{
              role: 'user',
              parts: [
                { inlineData: { mimeType: imgMime, data: base64Data } },
                { text: 'Baca foto struk/nota belanja ini secara teliti. Tuliskan rincian lengkap: nama barang, kuantitas, harga satuan, dan total harga yang tertera.' }
              ]
            }]
          },
          json: true, timeout: 15000
        });

        if (res && res.candidates && res.candidates.length > 0) {
          const textPart = res.candidates[0].content?.parts?.[0]?.text || '';
          if (textPart.trim()) {
            extractedReceiptText = textPart.trim();
            break;
          }
        }
      } catch (err) {}
    }

    // [PRIORITAS 2: GROQ QWEN 3.6 VISION - CADANGAN VISION 1]
    if (!extractedReceiptText) {
      try {
        const groqVisionRes = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://api.groq.com/openai/v1/chat/completions',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + GROQ_API_KEY
          },
          body: {
            model: 'qwen/qwen3.6-27b',
            messages: [{
              role: 'user',
              content: [
                { type: 'text', text: 'Baca foto struk belanja ini. Sebutkan nama barang, kuantitas, harga, dan total belanja.' },
                { type: 'image_url', image_url: { url: 'data:' + imgMime + ';base64,' + base64Data } }
              ]
            }]
          },
          json: true, timeout: 15000
        });

        if (groqVisionRes?.choices?.[0]?.message?.content) {
          extractedReceiptText = groqVisionRes.choices[0].message.content.trim();
        }
      } catch (err) {}
    }

    // [PRIORITAS 3: VIBE AI VISION - 3-TIER MODEL MATRIX]
    // Tier 1: free/gpt-5.6-luna -> Tier 2: free/grok-4.5 -> Tier 3: free/grok-4.6
    if (!extractedReceiptText) {
      const vibeVisionCandidates = ['free/gpt-5.6-luna', 'free/grok-4.5', 'free/grok-4.6'];
      for (const vModel of vibeVisionCandidates) {
        try {
          const vibeVisionRes = await this.helpers.httpRequest({
            method: 'POST',
            url: 'https://vibe.madewgn.dev/v1/chat/completions',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ' + VIBE_API_KEY
            },
            body: {
              model: vModel,
              messages: [{
                role: 'user',
                content: [
                  { type: 'text', text: 'Baca foto struk belanja ini. Sebutkan nama barang, kuantitas, harga, dan total belanja.' },
                  { type: 'image_url', image_url: { url: 'data:' + imgMime + ';base64,' + base64Data } }
                ]
              }]
            },
            json: true,
            timeout: 10000
          });

          if (vibeVisionRes?.choices?.[0]?.message?.content) {
            extractedReceiptText = vibeVisionRes.choices[0].message.content.trim();
            break;
          }
        } catch (err) {}
      }
    }

    // Lampirkan juga binary file agar agent Gemini tetap memiliki akses gambar visual
    binary.data = {
      data: base64Data,
      mimeType: imgMime,
      fileExtension: 'jpg',
      fileName: 'wa_receipt.jpg'
    };
  }

  if (extractedReceiptText) {
    promptText = 'Berikut adalah data rincian transaksi belanja yang terbaca dari foto struk:\n' + extractedReceiptText + '\n\nTolong catat seluruh rincian transaksi ini secara otomatis ke database menggunakan tool yang sesuai.';
  } else {
    promptText = 'Pengguna mengirimkan foto struk belanja. Mohon baca nama barang, kuantitas, harga satuan, dan total harga pada gambar terlampir lalu catat otomatis ke database.';
  }
}

return {
  json: {
    ...prev,
    user_prompt: promptText
  },
  binary: Object.keys(binary).length > 0 ? binary : undefined
};

let raw = $json.transactions;
const currentUserId = String($json.user_id || $('WhatsApp Input Normalizer').first().json.chat_id || '');

let rows;
try {
  rows = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  return JSON.stringify({ error: "Data transaksi tidak valid." });
}

if (!Array.isArray(rows)) {
  rows = [rows];
}

// 1. FILTER MULTI-TENANT ISOLATION (HANYA MILIK NOMOR AKTIF INI)
const userRows = rows.filter(row => {
  const data = row.json ?? row;
  if (!data) return false;
  if (data.description && String(data.description).includes(`[UID:${currentUserId}]`)) return true;
  if (data.user_id && String(data.user_id) === currentUserId) return true;
  return false;
});

// 2. DETEKSI KOREKSI / RALAT / VOID (AUTOMATIC DE-DUPLICATION & SUPERSEDING)
const supersededKeys = new Set();
const correctionNotes = [];

for (const row of userRows) {
  const data = row.json ?? row;
  const desc = ((data.description || '') + ' ' + (data.product || '')).toLowerCase();
  const rowId = data.id || data.transaction_id;

  // Cek pola koreksi: "koreksi dari X", "ralat dari X", "ganti dari X", "[VOID:X]"
  const matchCorrection = desc.match(/(?:koreksi|ralat|ganti)\s+dari\s+([a-zA-Z0-9_\s]+?)(?:\)|$|,|\])/i);
  const matchVoid = desc.match(/\[void:([^\]]+)\]/i);

  if (matchCorrection) {
    const targetName = matchCorrection[1].trim().toLowerCase();
    for (const prev of userRows) {
      const prevData = prev.json ?? prev;
      const prevId = prevData.id || prevData.transaction_id;
      if (prevId && prevId !== rowId) {
        const prevProd = (prevData.product || '').toLowerCase();
        const prevDesc = (prevData.description || '').toLowerCase();
        if (prevProd.includes(targetName) || prevDesc.includes(targetName)) {
          supersededKeys.add(prevId);
          correctionNotes.push(`Data keliru [${prevData.product}] telah otomatis dibatalkan dan diperbarui menjadi [${data.product}]`);
        }
      }
    }
  }

  if (matchVoid) {
    const voidTarget = matchVoid[1].trim().toLowerCase();
    for (const prev of userRows) {
      const prevData = prev.json ?? prev;
      const prevId = String(prevData.id || prevData.transaction_id || '').toLowerCase();
      const prevProd = (prevData.product || '').toLowerCase();
      if (prevId.includes(voidTarget) || prevProd.includes(voidTarget)) {
        supersededKeys.add(prevData.id || prevData.transaction_id);
        correctionNotes.push(`Transaksi [${prevData.product}] dibatalkan secara permanen.`);
      }
    }
  }
