// Saring transaksi aktif yang tidak dibatalkan / tidak dikoreksi
const activeUserRows = userRows.filter(row => {
  const data = row.json ?? row;
  const rowId = data.id || data.transaction_id;
  if (supersededKeys.has(rowId)) return false;
  if (data.type === 'void' || data.category === 'void') return false;
