});

let totalIncome = 0;
let totalExpense = 0;
let salesIncome = 0;

let salesList = [];
let expenseList = [];
let kasbonList = [];
let pelunasanList = [];

let kasbonPerPerson = {}; // Akumulasi Kasbon per Orang
let productSummary = {};

for (const row of activeUserRows) {
  const data = row.json ?? row;
  const amount = Number(data.amount || 0);
  const qty = Number(data.quantity || 1);
  const unitPrice = Number(data.unit_price || amount);
  const prod = data.product || 'Lain-lain';
  const category = (data.category || '').toLowerCase();
  const type = (data.type || '').toLowerCase();
  const date = data.date || '';
  const desc = data.description || '';

  if (!Number.isFinite(amount) || amount <= 0) continue;

  const prodLower = prod.toLowerCase();

  // 1. PELUNASAN KASBON
  if (category.includes('pelunasan') || prodLower.includes('pelunasan') || type === 'debt_payment') {
    const rawName = prod.replace(/pelunasan\s*(kasbon)?\s*:?/i, '').replace(/kasbon\s*:?/i, '').trim();
    const cleanName = rawName.length > 0 ? rawName : 'Pelanggan';
    const key = cleanName.toLowerCase();

    if (!kasbonPerPerson[key]) {
      kasbonPerPerson[key] = { name: cleanName, totalKasbon: 0, totalBayar: 0, sisaKasbon: 0, logs: [] };
    }
    kasbonPerPerson[key].totalBayar += amount;
    kasbonPerPerson[key].sisaKasbon -= amount;
    kasbonPerPerson[key].logs.push({ type: 'bayar', amount, date });

    pelunasanList.push({
      nama: cleanName,
      nominal: amount,
      tanggal: date
    });
    totalIncome += amount;
    continue;
  }

  // 2. KASBON / PIUTANG BARU
  if (category.includes('kasbon') || prodLower.startsWith('kasbon') || type === 'receivable') {
    const rawName = prod.replace(/kasbon\s*:?/i, '').trim();
    const cleanName = rawName.length > 0 ? rawName : 'Pelanggan';
    const key = cleanName.toLowerCase();

    if (!kasbonPerPerson[key]) {
      kasbonPerPerson[key] = { name: cleanName, totalKasbon: 0, totalBayar: 0, sisaKasbon: 0, logs: [] };
    }
    kasbonPerPerson[key].totalKasbon += amount;
    kasbonPerPerson[key].sisaKasbon += amount;
    kasbonPerPerson[key].logs.push({ type: 'kasbon', amount, date, desc });

    kasbonList.push({
      nama: cleanName,
      nominal: amount,
      tanggal: date,
      qty,
      unitPrice,
      deskripsi: desc
    });
    continue;
  }

  // 3. PENJUALAN MURNI (SALES / INCOME)
  if (type === "income") {
    totalIncome += amount;
    if (category === "sales" || !category) {
      salesIncome += amount;
    }
    productSummary[prod] = (productSummary[prod] || 0) + qty;
    salesList.push({
      produk: prod,
      qty,
      unitPrice,
      total: amount,
      tanggal: date
    });
    continue;
  }

  // 4. PENGELUARAN MURNI (EXPENSE)
  if (type === "expense") {
    totalExpense += amount;
    expenseList.push({
      kebutuhan: prod,
      qty,
      unitPrice,
      total: amount,
      kategori: category,
      tanggal: date
    });
    continue;
  }
}

// Hitung Kasbon Aktif (Sisa > 0)
let daftarKasbonAktif = [];
let totalSisaKasbon = 0;

for (const key in kasbonPerPerson) {
  const p = kasbonPerPerson[key];
  if (p.sisaKasbon > 0) {
    totalSisaKasbon += p.sisaKasbon;
    daftarKasbonAktif.push({
      nama: p.name,
      totalKasbon: p.totalKasbon,
      totalSudahDibayar: p.totalBayar,
      sisaKasbon: p.sisaKasbon
    });
  }
}

const balance = totalIncome - totalExpense;

// Top Produk Terlaris
const sortedProducts = Object.entries(productSummary)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3)
  .map(([name, qty]) => `${name} (${qty}x)`);

return JSON.stringify({
  totalIncome,
  totalExpense,
  salesIncome,
  balance,
  totalSisaKasbon,
  daftarKasbonAktif: daftarKasbonAktif.length > 0 ? daftarKasbonAktif : "Tidak ada kasbon aktif yang belum lunas",
  daftarPelunasan: pelunasanList.length > 0 ? pelunasanList : "Belum ada data pelunasan kasbon",
  daftarPenjualanMurni: salesList,
  daftarPengeluaranMurni: expenseList,
  rekapPerOrang: kasbonPerPerson,
  koreksiDiterapkan: correctionNotes.length > 0 ? correctionNotes : ["Semua data transaksi valid dan tidak ada koreksi bertumpuk"],
  topSellingProducts: sortedProducts.length > 0 ? sortedProducts : ["Belum ada data penjualan murni"]
});

const targetPerson = $json.person_name || 'Pelanggan';
const amount = Number($json.amount || $json.total_sisa_kasbon) || 0;

const politeDraft = `Halo Kak ${targetPerson}, semoga sehat selalu ya. Sekadar mengingatkan dengan ramah terkait total catatan kasbon sebesar Rp${amount.toLocaleString('id-ID')} yang belum lunas. Jika sudah senggang, pembayarannya bisa ditransfer via QRIS/BCA ya Kak. Terima kasih banyak atas kerjasamanya! 🙏✨`;

return JSON.stringify({
  status: "success",
  target_person: targetPerson,
  total_sisa_kasbon: amount,
  draft_message: politeDraft
});

