for (const data of rows) {
  const id = String(data.transaction_id || data.id || '').toLowerCase();
  const desc = String(data.description || '');
  if (!data || data.type === 'void' || data.category === 'void' || voided.has(id)) continue;
  const amount = Number(data.amount || 0);
  if (!Number.isFinite(amount) || amount <= 0) continue;
  const product = String(data.product || '');
  const category = String(data.category || '').toLowerCase();
  const type = String(data.type || '').toLowerCase();
  const uid = desc.match(/\[UID:(\d+)\]/i)?.[1];
  if (!uid) continue;
  const person = product.replace(/(?:pelunasan\s*)?(?:kasbon)?\s*:?/i, '').trim() || 'Pelanggan';
  const key = uid + '::' + person.toLowerCase();
  const prior = balances.get(key) || 0;
  if (category.includes('pelunasan') || product.toLowerCase().includes('pelunasan') || type === 'debt_payment') { balances.set(key, prior - amount); continue; }
  if (!(category.includes('kasbon') || product.toLowerCase().startsWith('kasbon') || type === 'receivable')) continue;
  balances.set(key, prior + amount);
  const dueValue = desc.match(/\[DUE:([^\]]+)\]/i)?.[1];
  const sentMarker = desc.match(/\[REMINDER_SENT:([^\]]+)\]/i);
  if (sentMarker) continue;
