if(scope==='riwayat'||scope==='rekap'){out+='\n*Pemasukan:*\n'+(income.map((r,i)=>`${i+1}. ${r.product||r.category||'Transaksi'} (${r.quantity||1} x ${money(r.unit_price||r.amount)}) = ${money(r.amount)}`).join('\n')||'Tidak ada')+'\n\n*Pengeluaran:*\n'+(expense.map((r,i)=>`${i+1}. ${r.product||r.category||'Transaksi'} (${r.quantity||1} x ${money(r.unit_price||r.amount)}) = ${money(r.amount)}`).join('\n')||'Tidak ada')+'\n';}
if(scope==='kasbon'||scope==='rekap'){const by={};for(const r of receivable){const m=String(r.description||r.product||'').match(/kasbon\s+([^\[]+)/i);const k=(m?m[1]:'Pelanggan').trim();by[k]=(by[k]||0)+Number(r.amount||0);}for(const r of payment){const m=String(r.description||r.product||'').match(/(?:pelunasan|bayar)\s+(?:kasbon\s+)?([^\[]+)/i);const k=(m?m[1]:'Pelanggan').trim();by[k]=(by[k]||0)-Number(r.amount||0);}out+='\n*Kasbon belum lunas:*\n'+(Object.entries(by).filter(([,v])=>v>0).map(([k,v],i)=>`${i+1}. ${k}: ${money(v)}`).join('\n')||'Tidak ada kasbon aktif')+'\n';}
if(scope==='reminder'){const due=data.filter(r=>String(r.description||'').includes('[DUE:'));out+=(due.map((r,i)=>`${i+1}. ${r.description}`).join('\n')||'Tidak ada pengingat pada periode ini')+'\n';}
cache.reportCache[key]={output:out,at:Date.now()};
return [{json:{output:out,requested_report:scope,report_period:period}}];

const input = $('WhatsApp Input Normalizer').first().json;
const state = $getWorkflowStaticData('global');
const now = Date.now();
state.umkmRate = state.umkmRate || {};
const key = String(input.chat_id || input.user_id || 'unknown');
const s = state.umkmRate[key] || { light: [], heavy: [] };
s.light = s.light.filter(t => now - t < 30000);
s.heavy = s.heavy.filter(t => now - t < 60000);
const heavy = Boolean(input.has_media || input.is_export);
const exceeded = s.light.length >= 15 || (heavy && s.heavy.length >= 2);
if (!exceeded) { s.light.push(now); if (heavy) s.heavy.push(now); }
state.umkmRate[key] = s;
return [{ json: { ...input, rate_limited: exceeded, rate_limit_kind: heavy ? 'heavy' : 'light' } }];

